using C64Lib;

// The soundtrack and effect data: generated by audio/score.py (the readable
// source), embedded here for C64.Music (asm/C64Music.asm) to play.
#if SCENE_AUDIO_SFXGATED
[assembly: RawAssembly(Order = 10, Resource = "Catacombs.audio.music_test.asm")] // + a test fixture song
#else
[assembly: RawAssembly(Order = 10, Resource = "Catacombs.audio.music.asm")]
#endif

namespace Catacombs;

// Everything the player hears. Gameplay code calls one of these at the
// moment something happens; which song or effect that means is decided
// here. Music runs from the interrupt (see C64.Music.Install), so none of
// these calls block unless they say so.
static class Audio
{
    const uint StepEvery = 24;  // frames between two footsteps: about two a second

    static uint lastStep_;      // C64.Music.Frame of the last footstep
    static bool walking_;
    static bool stepLeft_;

    // A song from its start (the title tune hands over to the exploration
    // tune by itself after 8.6 s -- on purpose: a player idling on the
    // title screen hears the game's main tune, and Song(SongExplore) at
    // the start of a run restarts it from bar 1), and a sound effect: for the moments that need
    // nothing more (door, pickups, the sword's blow -- which the monster's
    // growl outranks, so the growl answering it is never dropped).
    public static void Song(uint song)
    {
        C64.Music.Play(song);
    }

    public static void Fx(uint effect)
    {
        C64.Music.PlayEffect(effect);
    }

    // Once, at boot.
    public static void Init()
    {
        C64.Music.Install();
#if SCENE_AUDIO_EXPLORE
        Hold(AudioIds.SongExplore);
#elif SCENE_AUDIO_COMBAT
        Hold(AudioIds.SongCombat);
#elif SCENE_AUDIO_TITLE
        Hold(AudioIds.SongTitle);
#elif SCENE_AUDIO_DEATH
        Hold(AudioIds.SongDeath);
#elif SCENE_AUDIO_VICTORY
        C64.Music.Play(AudioIds.SongExplore);
        Wait(250);
        C64.Music.Interrupt(AudioIds.SongVictory); // resumes the exploration tune by itself
        Forever();
#elif SCENE_AUDIO_RESUME
        C64.Music.Play(AudioIds.SongExplore);
        Wait(250);
        Wait(250);
        C64.Music.Interrupt(AudioIds.SongCombat);
        Wait(250);
        C64.Music.Resume();
        Forever();
#elif SCENE_AUDIO_SFX
        EffectReel();
#elif SCENE_AUDIO_SFXMIX
        C64.Music.Play(AudioIds.SongExplore);
        EffectReel();
#elif SCENE_AUDIO_SFXCOMBAT
        C64.Music.Play(AudioIds.SongCombat);
        EffectReel();
#elif SCENE_AUDIO_SFXGATED
        C64.Music.Play(AudioIds.SongHold);
        EffectReel();
#endif
    }

    // Every pass of the main loop: did the player move? Footsteps come
    // at most two a second (timed in real frames, however long a pass
    // takes), left and right alternating, the first as soon as the player
    // sets off.
    public static void Step(bool moved)
    {
        if (!moved)
        {
            walking_ = false;
            return;
        }
        uint now = C64.Music.Frame;
        if (walking_ && (uint)(now - lastStep_) < StepEvery)
            return;
        walking_ = true;
        lastStep_ = now;
        C64.Music.PlayEffect(stepLeft_ ? AudioIds.FxStepA : AudioIds.FxStepB);
        stepLeft_ = !stepLeft_;
    }

    // The exploration tune is put aside, not stopped: MonsterDied picks it
    // up where it was.
    public static void CombatStart()
    {
        C64.Music.Interrupt(AudioIds.SongCombat);
        C64.Music.PlayEffect(AudioIds.FxGrowl);
    }

    // The monster strikes back: its growl, then the player's cry.
    public static void MonsterAttack()
    {
        C64.Music.PlayEffect(AudioIds.FxGrowl);
        Wait(30);
        C64.Music.PlayEffect(AudioIds.FxHurt);
    }

    public static void MonsterDied()
    {
        C64.Music.Resume();
        C64.Music.PlayEffect(AudioIds.FxMonsterDeath);
    }

    // Comes straight after MonsterAttack on a fatal blow: let the cry be
    // heard first.
    public static void PlayerDied()
    {
        Wait(16);
        C64.Music.PlayEffect(AudioIds.FxPlayerDeath);
        C64.Music.Play(AudioIds.SongDeath); // hands over to the exploration tune by itself
    }

    static void Wait(uint frames)
    {
        for (uint i = 0; i < frames; i++)
            C64.Screen.WaitForVBlank();
    }

#if SCENE_AUDIO_EXPLORE || SCENE_AUDIO_COMBAT || SCENE_AUDIO_TITLE || SCENE_AUDIO_DEATH || SCENE_AUDIO_VICTORY || SCENE_AUDIO_RESUME || SCENE_AUDIO_SFX || SCENE_AUDIO_SFXMIX || SCENE_AUDIO_SFXCOMBAT || SCENE_AUDIO_SFXGATED
    // Audio scene builds (see audio/README.md): play one thing from boot and
    // stay there, for recording.
    static void Hold(uint song)
    {
        C64.Music.Play(song);
        Forever();
    }

    // Every effect in turn, two seconds (100 frames) apart.
    static void EffectReel()
    {
        Wait(50);
        for (uint i = 0; i <= AudioIds.FxPlayerDeath; i++)
        {
            C64.Music.PlayEffect(i);
            Wait(100);
        }
        Forever();
    }

    // (A loop the compiler can see no way out of doesn't compile in a
    // method of its own, hence the flag.)
    static bool holding_ = true;

    static void Forever()
    {
        while (holding_)
            C64.Screen.WaitForVBlank();
    }
#endif
}
